/**
 * The normative SVG serializer.
 *
 * The output of this function is the normative figure. Its bytes are hashed and
 * cross-checked, so the serializer is written to be deterministic to the byte and safe
 * against a hostile label.
 *
 * Two properties matter most:
 *
 *   Determinism. No clock, no random id, no locale. Element ids derive from the canonical
 *   request digest plus deterministic local ids. Using the artifact digest would be cyclic
 *   because the artifact binds these SVG bytes. They never derive from React's useId or a UUID. Attribute order is
 *   fixed. Coordinates use the fixed formatter. There is no generator timestamp — one
 *   would make two identical figures hash two ways.
 *
 *   Safety. This is a purpose-built writer over a CLOSED vocabulary, not string
 *   interpolation scattered across figure code. XML text and attribute values are
 *   escaped independently. There is no path by which a caller-supplied title, unit, or
 *   note can introduce a `<script>`, an `on*` handler, a `<foreignObject>`, or an
 *   external URL — because those are simply not elements this writer can emit. A hostile
 *   label becomes escaped text, nothing more.
 */

import type {
  RenderPlanV1,
  Panel,
  Mark,
  Axis,
  TextMark,
} from './model/renderPlan.js';
import { formatCoordinate } from './format.js';
import { THEMES } from '../generated/catalog.js';
import { ARTIFACT_CONTRACT } from '../generated/identity.js';
import {
  DISCLOSURE_BOTTOM_PADDING,
  DISCLOSURE_FONT_SIZE,
  DISCLOSURE_HORIZONTAL_INSET,
  DISCLOSURE_LINE_HEIGHT,
  LEGEND_ROW_HEIGHT,
  disclosureLineCount,
  disclosureRenderedTextLength,
  legendColumnCount,
  legendStartY,
  wrapDisclosureText,
} from './layout.js';
import { isClosedPlainRenderPlanForAuthorityV1 } from './plan-closure.js';

/** A closed-plan geometry contradiction. Serialization never repairs or drops it. */
export class RenderPlanGeometryError extends Error {
  constructor(
    readonly panelId: string,
    readonly markPath: string,
    message: string,
  ) {
    super(message);
    this.name = 'RenderPlanGeometryError';
  }
}

function assertArrowGeometry(
  marks: readonly Mark[],
  panelId: string,
  prefix = 'marks',
): void {
  for (let markIndex = 0; markIndex < marks.length; markIndex++) {
    const mark = marks[markIndex];
    const markPath = `${prefix}/${markIndex}`;
    if (mark.type === 'group') {
      assertArrowGeometry(mark.marks, panelId, `${markPath}/marks`);
      continue;
    }
    if (mark.type !== 'arrow') continue;
    if (!Number.isFinite(mark.size) || !(mark.size > 0)) {
      throw new RenderPlanGeometryError(
        panelId,
        `${markPath}/size`,
        `arrow size must be finite and strictly positive; got ${String(mark.size)}`,
      );
    }
    for (let arrowIndex = 0; arrowIndex < mark.arrows.length; arrowIndex++) {
      const arrow = mark.arrows[arrowIndex];
      if (![arrow.from.x, arrow.from.y, arrow.to.x, arrow.to.y].every(Number.isFinite)) {
        throw new RenderPlanGeometryError(
          panelId,
          `${markPath}/arrows/${arrowIndex}`,
          'arrow endpoints must contain four finite coordinates',
        );
      }
      if (arrow.from.x === arrow.to.x && arrow.from.y === arrow.to.y) {
        throw new RenderPlanGeometryError(
          panelId,
          `${markPath}/arrows/${arrowIndex}`,
          'arrow endpoints are identical, so direction is undefined',
        );
      }
    }
  }
}

/** Validate direction-bearing geometry before resource accounting or byte emission. */
export function assertRenderPlanGeometry(plan: RenderPlanV1): void {
  for (const panel of plan.panels) assertArrowGeometry(panel.marks, panel.id);
}

/** Escape text content: the five XML text-significant characters. */
function escapeText(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** Escape an attribute value: text-significant characters plus both quote styles. */
function escapeAttribute(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * A minimal, deterministic XML writer over a fixed element/attribute set.
 *
 * The `attrs` array preserves insertion order, and every emitter below writes attributes
 * in a fixed order — so the serialized bytes are stable rather than dependent on object
 * key iteration.
 */
class SvgWriter {
  private out: string[] = [];
  private indentLevel = 0;

  private indent(): string {
    return '  '.repeat(this.indentLevel);
  }

  open(tag: string, attrs: readonly [string, string | number][] = []): this {
    const rendered = attrs
      .map(([key, value]) => `${key}="${escapeAttribute(String(value))}"`)
      .join(' ');
    this.out.push(`${this.indent()}<${tag}${rendered ? ` ${rendered}` : ''}>`);
    this.indentLevel++;
    return this;
  }

  leaf(tag: string, attrs: readonly [string, string | number][] = []): this {
    const rendered = attrs
      .map(([key, value]) => `${key}="${escapeAttribute(String(value))}"`)
      .join(' ');
    this.out.push(`${this.indent()}<${tag}${rendered ? ` ${rendered}` : ''}/>`);
    return this;
  }

  text(tag: string, content: string, attrs: readonly [string, string | number][] = []): this {
    const rendered = attrs
      .map(([key, value]) => `${key}="${escapeAttribute(String(value))}"`)
      .join(' ');
    this.out.push(
      `${this.indent()}<${tag}${rendered ? ` ${rendered}` : ''}>${escapeText(content)}</${tag}>`,
    );
    return this;
  }

  close(tag: string): this {
    this.indentLevel--;
    this.out.push(`${this.indent()}</${tag}>`);
    return this;
  }

  raw(line: string): this {
    this.out.push(`${this.indent()}${line}`);
    return this;
  }

  toString(): string {
    // A trailing newline, fixed, so the byte sequence is complete and stable.
    return `${this.out.join('\n')}\n`;
  }
}

function theme(themeId: string): Record<string, string> {
  return (THEMES as Record<string, Record<string, string>>)[themeId] ?? THEMES.light;
}

function pointsToPath(points: readonly { x: number; y: number }[]): string {
  if (points.length === 0) return '';
  const commands = points.map(
    (point, index) =>
      `${index === 0 ? 'M' : 'L'}${formatCoordinate(point.x)},${formatCoordinate(point.y)}`,
  );
  return commands.join(' ');
}

const MARKER_PATHS: Record<string, (x: number, y: number, r: number) => string> = {
  circle: (x, y, r) => `M${formatCoordinate(x - r)},${formatCoordinate(y)}a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0`,
  square: (x, y, r) => `M${formatCoordinate(x - r)},${formatCoordinate(y - r)}h${2 * r}v${2 * r}h${-2 * r}z`,
  triangle: (x, y, r) => `M${formatCoordinate(x)},${formatCoordinate(y - r)}L${formatCoordinate(x + r)},${formatCoordinate(y + r)}L${formatCoordinate(x - r)},${formatCoordinate(y + r)}z`,
  diamond: (x, y, r) => `M${formatCoordinate(x)},${formatCoordinate(y - r)}L${formatCoordinate(x + r)},${formatCoordinate(y)}L${formatCoordinate(x)},${formatCoordinate(y + r)}L${formatCoordinate(x - r)},${formatCoordinate(y)}z`,
  cross: (x, y, r) => `M${formatCoordinate(x - r)},${formatCoordinate(y - r)}L${formatCoordinate(x + r)},${formatCoordinate(y + r)}M${formatCoordinate(x + r)},${formatCoordinate(y - r)}L${formatCoordinate(x - r)},${formatCoordinate(y + r)}`,
  plus: (x, y, r) => `M${formatCoordinate(x - r)},${formatCoordinate(y)}L${formatCoordinate(x + r)},${formatCoordinate(y)}M${formatCoordinate(x)},${formatCoordinate(y - r)}L${formatCoordinate(x)},${formatCoordinate(y + r)}`,
  star: (x, y, r) => {
    const points: { x: number; y: number }[] = [];
    for (let index = 0; index < 10; index++) {
      const radius = index % 2 === 0 ? r : r * 0.42;
      const angle = -Math.PI / 2 + index * Math.PI / 5;
      points.push({ x: x + radius * Math.cos(angle), y: y + radius * Math.sin(angle) });
    }
    return `${pointsToPath(points)} Z`;
  },
  hexagon: (x, y, r) => {
    const points = Array.from({ length: 6 }, (_value, index) => {
      const angle = Math.PI / 6 + index * Math.PI / 3;
      return { x: x + r * Math.cos(angle), y: y + r * Math.sin(angle) };
    });
    return `${pointsToPath(points)} Z`;
  },
};

function emitMark(writer: SvgWriter, mark: Mark, colors: Record<string, string>): void {
  switch (mark.type) {
    case 'line': {
      const d = mark.subpaths
        .filter((subpath) => subpath.length > 0)
        .map((subpath) => pointsToPath(subpath))
        .join(' ');
      if (d.length === 0) return;
      const attrs: [string, string | number][] = [
        ['d', d],
        ['fill', 'none'],
        ['stroke', mark.stroke],
        ['stroke-width', mark.strokeWidth],
      ];
      if (mark.dash && mark.dash !== 'none') attrs.push(['stroke-dasharray', mark.dash]);
      writer.leaf('path', attrs);
      break;
    }
    case 'arrow': {
      for (const arrow of mark.arrows) {
        const dx = arrow.to.x - arrow.from.x;
        const dy = arrow.to.y - arrow.from.y;
        const length = Math.hypot(dx, dy);
        if (!(length > 0) || !Number.isFinite(length)) {
          throw new RenderPlanGeometryError(
            'unknown',
            'marks/arrow',
            'arrow direction became non-finite or degenerate during serialization',
          );
        }
        const ux = dx / length;
        const uy = dy / length;
        const bx = arrow.to.x - ux * mark.size;
        const by = arrow.to.y - uy * mark.size;
        const halfWidth = mark.size * 0.58;
        const px = -uy * halfWidth;
        const py = ux * halfWidth;
        const d = [
          `M${formatCoordinate(arrow.to.x)},${formatCoordinate(arrow.to.y)}`,
          `L${formatCoordinate(bx + px)},${formatCoordinate(by + py)}`,
          `L${formatCoordinate(bx - px)},${formatCoordinate(by - py)} Z`,
        ].join(' ');
        writer.leaf('path', [
          ['d', d],
          ['fill', mark.fill],
          ['stroke', mark.fill],
          ['stroke-width', 1],
        ]);
      }
      break;
    }
    case 'path': {
      const d = mark.subpaths
        .filter((subpath) => subpath.length > 0)
        .map((subpath) => pointsToPath(subpath))
        .join(' ');
      if (d.length === 0) return;
      writer.leaf('path', [
        ['d', d],
        ['fill', 'none'],
        ['stroke', mark.stroke],
        ['stroke-width', mark.strokeWidth],
      ]);
      break;
    }
    case 'point': {
      const build = MARKER_PATHS[mark.shape] ?? MARKER_PATHS.circle;
      for (const point of mark.points) {
        writer.leaf('path', [
          ['d', build(point.x, point.y, mark.radius)],
          ['fill', mark.fill],
          ['stroke', mark.fill],
          ['stroke-width', 1],
        ]);
      }
      break;
    }
    case 'rect': {
      for (const rect of mark.rects) {
        const attrs: [string, string | number][] = [
          ['x', formatCoordinate(rect.x)],
          ['y', formatCoordinate(rect.y)],
          ['width', formatCoordinate(Math.max(0, rect.width))],
          ['height', formatCoordinate(Math.max(0, rect.height))],
          ['fill', rect.fill],
        ];
        if (mark.stroke) attrs.push(['stroke', mark.stroke]);
        writer.leaf('rect', attrs);
      }
      break;
    }
    case 'rule': {
      for (const line of mark.lines) {
        const attrs: [string, string | number][] =
          mark.orientation === 'vertical'
            ? [
                ['x1', formatCoordinate(line.position)],
                ['y1', formatCoordinate(line.from)],
                ['x2', formatCoordinate(line.position)],
                ['y2', formatCoordinate(line.to)],
              ]
            : [
                ['x1', formatCoordinate(line.from)],
                ['y1', formatCoordinate(line.position)],
                ['x2', formatCoordinate(line.to)],
                ['y2', formatCoordinate(line.position)],
              ];
        attrs.push(['stroke', mark.stroke], ['stroke-width', mark.strokeWidth]);
        if (mark.dash && mark.dash !== 'none') attrs.push(['stroke-dasharray', mark.dash]);
        writer.leaf('line', attrs);
      }
      break;
    }
    case 'area': {
      for (const subpath of mark.subpaths) {
        if (subpath.length === 0) continue;
        const top = subpath.map((p) => ({ x: p.x, y: p.y1 }));
        const bottom = subpath.map((p) => ({ x: p.x, y: p.y0 })).reverse();
        const d = `${pointsToPath(top)} ${pointsToPath(bottom).replace(/^M/, 'L')} Z`;
        const attrs: [string, string | number][] = [
          ['d', d],
          ['fill', mark.fill],
          ['fill-opacity', mark.opacity],
          ['stroke', mark.stroke ?? 'none'],
        ];
        if (mark.stroke) attrs.push(['stroke-width', mark.strokeWidth ?? 1]);
        writer.leaf('path', attrs);
      }
      break;
    }
    case 'text':
      emitText(writer, mark);
      break;
    case 'group':
      writer.open('g', [['data-id', mark.id]]);
      for (const child of mark.marks) emitMark(writer, child, colors);
      writer.close('g');
      break;
  }
}

interface RotatedTextLayout {
  readonly angle: -90 | 90;
  readonly pivotX: number;
  readonly pivotY: number;
  readonly textLength: number;
}

function emitText(writer: SvgWriter, mark: TextMark, rotation?: RotatedTextLayout): void {
  const attrs: [string, string | number][] = [
    ['x', formatCoordinate(mark.x)],
    ['y', formatCoordinate(mark.y)],
    ['text-anchor', mark.anchor],
    ['font-size', mark.fontSize],
    ['fill', mark.fill],
    ['font-family', 'sans-serif'],
  ];
  // Decorative text is marked aria-hidden; the referenced description and returned
  // table carry the exact values separately. This is structural, not AT evidence.
  if (mark.decorative) attrs.push(['aria-hidden', 'true']);
  if (rotation) {
    const pivot = `${formatCoordinate(rotation.pivotX)} ${formatCoordinate(rotation.pivotY)}`;
    attrs.push(
      ['transform', `rotate(${rotation.angle} ${pivot})`],
      ['textLength', formatCoordinate(rotation.textLength)],
      ['lengthAdjust', 'spacingAndGlyphs'],
    );
  }
  writer.text('text', mark.text, attrs);
}

const AXIS_LABEL_FONT_SIZE = 12;
const AXIS_LABEL_VIEWPORT_INSET = AXIS_LABEL_FONT_SIZE;
const AXIS_LABEL_APPROXIMATE_ADVANCE = AXIS_LABEL_FONT_SIZE * 0.6;

function codePointCount(value: string): number {
  let count = 0;
  for (let index = 0; index < value.length; count++) {
    const codePoint = value.codePointAt(index)!;
    index += codePoint > 0xffff ? 2 : 1;
  }
  return count;
}

function emitAxis(
  writer: SvgWriter,
  axis: Axis,
  panel: Panel,
  colors: Record<string, string>,
  viewportWidth: number,
  viewportHeight: number,
): void {
  writer.open('g', [['data-axis', axis.orientation], ['aria-hidden', 'true']]);

  const isBottom = axis.orientation === 'bottom';
  const isLeft = axis.orientation === 'left';
  const isTop = axis.orientation === 'top';

  for (const tick of axis.ticks) {
    if (isBottom) {
      writer.leaf('line', [
        ['x1', formatCoordinate(tick.position)],
        ['y1', formatCoordinate(panel.y + panel.height)],
        ['x2', formatCoordinate(tick.position)],
        ['y2', formatCoordinate(panel.y + panel.height + 5)],
        ['stroke', colors.axis],
        ['stroke-width', 1],
      ]);
      emitText(writer, {
        type: 'text',
        x: tick.position,
        y: panel.y + panel.height + 18,
        text: tick.label,
        anchor: 'middle',
        fontSize: 11,
        fill: colors.mutedText,
        decorative: true,
      });
    } else if (isLeft) {
      writer.leaf('line', [
        ['x1', formatCoordinate(panel.x - 5)],
        ['y1', formatCoordinate(tick.position)],
        ['x2', formatCoordinate(panel.x)],
        ['y2', formatCoordinate(tick.position)],
        ['stroke', colors.axis],
        ['stroke-width', 1],
      ]);
      emitText(writer, {
        type: 'text',
        x: panel.x - 8,
        y: tick.position + 4,
        text: tick.label,
        anchor: 'end',
        fontSize: 11,
        fill: colors.mutedText,
        decorative: true,
      });
    } else if (isTop) {
      writer.leaf('line', [
        ['x1', formatCoordinate(tick.position)],
        ['y1', formatCoordinate(panel.y - 5)],
        ['x2', formatCoordinate(tick.position)],
        ['y2', formatCoordinate(panel.y)],
        ['stroke', colors.axis],
        ['stroke-width', 1],
      ]);
      emitText(writer, {
        type: 'text',
        x: tick.position,
        y: panel.y - 8,
        text: tick.label,
        anchor: 'middle',
        fontSize: 11,
        fill: colors.mutedText,
        decorative: true,
      });
    } else {
      writer.leaf('line', [
        ['x1', formatCoordinate(panel.x + panel.width)],
        ['y1', formatCoordinate(tick.position)],
        ['x2', formatCoordinate(panel.x + panel.width + 5)],
        ['y2', formatCoordinate(tick.position)],
        ['stroke', colors.axis],
        ['stroke-width', 1],
      ]);
      emitText(writer, {
        type: 'text',
        x: panel.x + panel.width + 8,
        y: tick.position + 4,
        text: tick.label,
        anchor: 'start',
        fontSize: 11,
        fill: colors.mutedText,
        decorative: true,
      });
    }
  }

  if (isBottom || isTop) {
    emitText(writer, {
      type: 'text',
      x: panel.x + panel.width / 2,
      y: isBottom ? panel.y + panel.height + 38 : panel.y - 28,
      text: axis.label,
      anchor: 'middle',
      fontSize: AXIS_LABEL_FONT_SIZE,
      fill: colors.text,
      decorative: true,
    });
  } else {
    const unclampedX = isLeft ? panel.x - 44 : panel.x + panel.width + 44;
    const maximumX = Math.max(
      AXIS_LABEL_VIEWPORT_INSET,
      viewportWidth - AXIS_LABEL_VIEWPORT_INSET,
    );
    const x = Math.min(maximumX, Math.max(AXIS_LABEL_VIEWPORT_INSET, unclampedX));
    const maximumY = Math.max(AXIS_LABEL_VIEWPORT_INSET, viewportHeight - AXIS_LABEL_VIEWPORT_INSET);
    const y = Math.min(
      maximumY,
      Math.max(AXIS_LABEL_VIEWPORT_INSET, panel.y + panel.height / 2),
    );
    const centeredViewportSpan = 2 * Math.max(0, Math.min(
      y - AXIS_LABEL_VIEWPORT_INSET,
      viewportHeight - AXIS_LABEL_VIEWPORT_INSET - y,
    ));
    const availableLength = Math.max(1, Math.min(panel.height, centeredViewportSpan));
    const intendedLength = Math.max(
      1,
      codePointCount(axis.label) * AXIS_LABEL_APPROXIMATE_ADVANCE,
    );
    const renderedLength = Math.min(intendedLength, availableLength);
    const angle = isLeft ? -90 : 90;
    emitText(writer, {
      type: 'text',
      x,
      y,
      text: axis.label,
      anchor: 'middle',
      fontSize: AXIS_LABEL_FONT_SIZE,
      fill: colors.text,
      decorative: true,
    }, {
      angle,
      pivotX: x,
      pivotY: y,
      textLength: renderedLength,
    });
  }

  writer.close('g');
}

export interface SvgReport {
  readonly svg: string;
  readonly digest: string;
  readonly markCount: number;
  readonly textCount: number;
  readonly width: number;
  readonly height: number;
}

function countMarks(marks: readonly Mark[]): { marks: number; texts: number } {
  let markCount = 0;
  let textCount = 0;
  const walk = (list: readonly Mark[]): void => {
    for (const mark of list) {
      switch (mark.type) {
        case 'group':
          walk(mark.marks);
          break;
        case 'line':
        case 'path':
          // The artifact's markCount and the `visibleMarks` budget name DRAWN marks, so
          // count the single SVG path this mark emits when it has any geometry. Vertex
          // work is bounded separately by observations and output bytes; calling every
          // vertex a visible mark would make a 10-bin step plot claim 20 marks while the
          // renderer actually draws one path.
          if (mark.subpaths.some((subpath) => subpath.length > 0)) markCount++;
          break;
        case 'arrow':
          markCount += mark.arrows.length;
          break;
        case 'point':
          markCount += mark.points.length;
          break;
        case 'rect':
          markCount += mark.rects.length;
          break;
        case 'rule':
          markCount += mark.lines.length;
          break;
        case 'area':
          markCount += mark.subpaths.filter((subpath) => subpath.length > 0).length;
          break;
        case 'text':
          markCount++;
          textCount++;
          break;
      }
    }
  };
  walk(marks);
  return { marks: markCount, texts: textCount };
}

/** Exact data-mark and SVG `<text>` counts implied by a render plan. */
export function countPlanResources(plan: RenderPlanV1): {
  readonly markCount: number;
  readonly textCount: number;
} {
  assertRenderPlanGeometry(plan);
  let markCount = 0;
  // The visible figure title is a `<text>` node; SVG `<title>` and `<desc>` are not.
  let textCount =
    1 +
    (plan.subtitle ? 1 : 0) +
    disclosureLineCount(plan.width, [...plan.disclosures, ...plan.sourceStatements]);

  for (const panel of plan.panels) {
    if (panel.label) textCount++;
    if (panel.noData) {
      textCount++;
      continue;
    }
    for (const axis of panel.axes) textCount += axis.ticks.length + 1;
    const counts = countMarks(panel.marks);
    markCount += counts.marks;
    textCount += counts.texts;
  }
  textCount += plan.legend?.length ?? 0;

  return { markCount, textCount };
}

function accessibleDetailText(plan: RenderPlanV1): string | null {
  const seen = new Set<string>([plan.accessibility.summary.trim()]);
  const details: string[] = [];
  const add = (value: string): void => {
    const normalized = value.trim();
    if (normalized.length === 0 || seen.has(normalized)) return;
    seen.add(normalized);
    details.push(normalized);
  };

  for (const summary of plan.accessibility.panelSummaries) add(summary);
  for (const panel of plan.panels) {
    if (!panel.noData) continue;
    const panelName = panel.label?.trim() || panel.id;
    add(`Panel ${panelName}: No data — ${panel.noData.reason}`);
  }
  return details.length > 0 ? details.join(' ') : null;
}

interface FigureTreeContainer {
  readonly kind: 'document' | 'translated_fragment';
  /**
   * Closed ASCII namespace owned by the future bundle compiler. It is deliberately
   * separate from `figureId`: two cells may lawfully contain the exact same request,
   * while SVG fragment identifiers remain document-wide.
   */
  readonly idNamespace?: string;
  readonly x?: number;
  readonly y?: number;
}

export interface TranslationOnlySvgFragmentOptions {
  /** Deterministic compiler-owned namespace, unique within the containing document. */
  readonly idNamespace: string;
  /** Non-negative integer translation in the future bundle's exact pixel grid. */
  readonly x: number;
  /** Non-negative integer translation in the future bundle's exact pixel grid. */
  readonly y: number;
}

export interface TranslationOnlySvgFragmentReport {
  readonly fragment: string;
  readonly digest: string;
  readonly idPrefix: string;
  readonly markCount: number;
  readonly textCount: number;
  readonly width: number;
  readonly height: number;
  readonly translation: Readonly<{ x: number; y: number }>;
}

const SVG_ID_NAMESPACE = /^[A-Za-z][A-Za-z0-9_-]{0,95}$/u;

function requireTranslationOnlyContainer(
  container: FigureTreeContainer,
  plan: RenderPlanV1,
): {
  readonly idPrefix: string;
  readonly x: number;
  readonly y: number;
} {
  const idNamespace = container.idNamespace;
  const x = container.x;
  const y = container.y;
  const planHasSafeIntegerExtent =
    Number.isSafeInteger(plan.width) &&
    plan.width > 0 &&
    Number.isSafeInteger(plan.height) &&
    plan.height > 0;
  if (
    typeof idNamespace !== 'string' ||
    !SVG_ID_NAMESPACE.test(idNamespace) ||
    !Number.isSafeInteger(x) ||
    Object.is(x, -0) ||
    (x as number) < 0 ||
    !Number.isSafeInteger(y) ||
    Object.is(y, -0) ||
    (y as number) < 0 ||
    !planHasSafeIntegerExtent ||
    (x as number) > Number.MAX_SAFE_INTEGER - plan.width ||
    (y as number) > Number.MAX_SAFE_INTEGER - plan.height
  ) {
    throw new Error(
      'translated SVG fragments require a 1-96 character closed ASCII id namespace, canonical non-negative safe-integer x/y offsets, and safe positive-integer child extents',
    );
  }
  return {
    idPrefix: `${idNamespace}-${plan.figureId}`,
    x: x as number,
    y: y as number,
  };
}

/**
 * Emit the exact figure tree inside either its historical standalone document root or
 * one future bundle-owned translation wrapper. Keeping both paths in this single
 * purpose-built writer makes the fragment path incapable of inventing a second mark,
 * caption, table projection, scale, clip, or hidden subtree.
 */
function emitFigureTree(
  plan: RenderPlanV1,
  digestOf: (text: string) => string,
  container: FigureTreeContainer,
): SvgReport {
  assertRenderPlanGeometry(plan);
  const colors = theme(plan.themeId);
  const writer = new SvgWriter();
  const accessibilityDetails = accessibleDetailText(plan);
  const translation = container.kind === 'translated_fragment'
    ? requireTranslationOnlyContainer(container, plan)
    : null;
  const idPrefix = translation?.idPrefix ?? plan.figureId;
  const labelledBy = `${idPrefix}-title`;
  const describedBy = accessibilityDetails === null
    ? `${idPrefix}-desc`
    : `${idPrefix}-desc ${idPrefix}-details`;

  if (translation === null) {
    writer.open('svg', [
      ['xmlns', 'http://www.w3.org/2000/svg'],
      ['xmlns:cortexel', 'urn:cortexel:metadata:1'],
      ['viewBox', `0 0 ${plan.width} ${plan.height}`],
      ['width', plan.width],
      ['height', plan.height],
      ['role', 'img'],
      ['aria-labelledby', labelledBy],
      ['aria-describedby', describedBy],
    ]);
  } else {
    // This wrapper intentionally has one geometric operation: integer translation.
    // It has no viewport, scale, clip, mask, opacity, visibility, or overflow policy.
    // A future bundle validator must separately prove that the plan's exact width and
    // height equal the declared cell viewport before this compiler-only path is called.
    writer.open('g', [
      ['data-cortexel-fragment', 'figure'],
      ['data-cortexel-id-namespace', container.idNamespace!],
      ['transform', `translate(${translation.x} ${translation.y})`],
      ['role', 'img'],
      ['aria-labelledby', labelledBy],
      ['aria-describedby', describedBy],
    ]);
  }

  // Figure-level title and description use distinct ARIA references.
  writer.text('title', plan.title, [['id', `${idPrefix}-title`]]);
  writer.text('desc', plan.accessibility.summary, [['id', `${idPrefix}-desc`]]);
  if (accessibilityDetails !== null) {
    writer.text('desc', accessibilityDetails, [['id', `${idPrefix}-details`]]);
  }

  // A compact, non-sensitive metadata block. Public identities only — no raw source
  // data, no local path, no token, no prompt.
  writer.open('metadata');
  writer.text('cortexel:contract', ARTIFACT_CONTRACT);
  writer.text('cortexel:skill', plan.skillId);
  writer.text('cortexel:requestDigest', plan.sourceRequestDigest);
  writer.close('metadata');

  writer.leaf('rect', [
    ['x', 0],
    ['y', 0],
    ['width', plan.width],
    ['height', plan.height],
    ['fill', colors.background],
  ]);

  emitText(writer, {
    type: 'text',
    x: 24,
    y: 28,
    text: plan.title,
    anchor: 'start',
    fontSize: 16,
    fill: colors.text,
    decorative: true, // the <title> element already names the figure for AT
  });

  if (plan.subtitle) {
    emitText(writer, {
      type: 'text',
      x: 24,
      y: 46,
      text: plan.subtitle,
      anchor: 'start',
      fontSize: 12,
      fill: colors.mutedText,
      decorative: true,
    });
  }

  if (plan.legend && plan.legend.length > 0) {
    const startY = legendStartY(plan.subtitle !== undefined);
    const columns = legendColumnCount(plan.width, plan.legend.length);
    const itemWidth = (plan.width - 48) / columns;
    writer.open('g', [['data-legend', 'true'], ['aria-hidden', 'true']]);
    for (let index = 0; index < plan.legend.length; index++) {
      const item = plan.legend[index];
      const outlineColor = item.outlineColor ?? item.color;
      const column = index % columns;
      const row = Math.floor(index / columns);
      const x = 24 + column * itemWidth;
      const y = startY + row * LEGEND_ROW_HEIGHT;
      const glyph = item.glyph ?? 'series';
      if (glyph === 'band') {
        writer.leaf('rect', [
          ['x', x],
          ['y', y - 9],
          ['width', 24],
          ['height', 10],
          ['fill', item.color],
          ['fill-opacity', 0.18],
          ['stroke', outlineColor],
          ['stroke-width', 1.5],
        ]);
      } else if (glyph === 'whisker') {
        writer.leaf('line', [
          ['x1', x + 12], ['y1', y - 10], ['x2', x + 12], ['y2', y + 2],
          ['stroke', outlineColor], ['stroke-width', 1.5],
        ]);
        for (const capY of [y - 10, y + 2]) {
          writer.leaf('line', [
            ['x1', x + 7], ['y1', capY], ['x2', x + 17], ['y2', capY],
            ['stroke', outlineColor], ['stroke-width', 1.5],
          ]);
        }
      } else {
        const attrs: [string, string | number][] = [
          ['x1', x],
          ['y1', y - 4],
          ['x2', x + 24],
          ['y2', y - 4],
          ['stroke', item.color],
          ['stroke-width', 1.5],
        ];
        if (item.dash && item.dash !== 'none') attrs.push(['stroke-dasharray', item.dash]);
        writer.leaf('line', attrs);
        if (item.marker) {
          const marker = MARKER_PATHS[item.marker] ?? MARKER_PATHS.circle;
          writer.leaf('path', [
            ['d', marker(x + 12, y - 4, 2.5)],
            ['fill', item.color],
            ['stroke', item.color],
            ['stroke-width', 1],
          ]);
        }
      }
      emitText(writer, {
        type: 'text',
        x: x + 32,
        y,
        text: item.label,
        anchor: 'start',
        fontSize: 10,
        fill: colors.text,
        decorative: true,
      });
    }
    writer.close('g');
  }

  for (const panel of plan.panels) {
    writer.open('g', [['data-panel', panel.id]]);

    if (panel.label) {
      emitText(writer, {
        type: 'text',
        x: panel.x,
        y: panel.y - 8,
        text: panel.label,
        anchor: 'start',
        fontSize: 11,
        fill: colors.text,
        decorative: true,
      });
    }

    if (panel.noData) {
      emitText(writer, {
        type: 'text',
        x: panel.x + panel.width / 2,
        y: panel.y + panel.height / 2,
        text: `No data: ${panel.noData.reason}`,
        anchor: 'middle',
        fontSize: 13,
        fill: colors.mutedText,
        decorative: true,
      });
    } else {
      for (const axis of panel.axes) {
        emitAxis(writer, axis, panel, colors, plan.width, plan.height);
      }
      for (const mark of panel.marks) {
        emitMark(writer, mark, colors);
      }
    }

    writer.close('g');
  }

  // Disclosures in normal flow at the foot of the figure, where they cannot be covered by
  // data. Every line is an exact substring of the registry text, and the enclosing group
  // carries that complete text for deterministic extraction. `textLength` makes the
  // horizontal bound independent of host font metrics.
  const footerLineCount = disclosureLineCount(
    plan.width,
    [...plan.disclosures, ...plan.sourceStatements],
  );
  let disclosureY =
    plan.height - footerLineCount * DISCLOSURE_LINE_HEIGHT - DISCLOSURE_BOTTOM_PADDING;
  writer.open('g', [['data-disclosures', 'true']]);
  for (const disclosure of plan.disclosures) {
    writer.open('g', [
      ['data-disclosure-id', disclosure.id],
      ['data-disclosure-text', disclosure.text],
    ]);
    const lines = wrapDisclosureText(disclosure.text, plan.width);
    for (let index = 0; index < lines.length; index++) {
      const line = lines[index];
      writer.text('text', line, [
        ['x', DISCLOSURE_HORIZONTAL_INSET],
        ['y', formatCoordinate(disclosureY)],
        ['text-anchor', 'start'],
        ['font-size', DISCLOSURE_FONT_SIZE],
        ['fill', disclosure.severity === 'critical' ? colors.error : colors.mutedText],
        ['font-family', 'sans-serif'],
        ['textLength', formatCoordinate(disclosureRenderedTextLength(line, plan.width))],
        ['lengthAdjust', 'spacingAndGlyphs'],
        ['data-disclosure-line', index],
        ['aria-hidden', 'true'],
      ]);
      disclosureY += DISCLOSURE_LINE_HEIGHT;
    }
    writer.close('g');
  }
  writer.close('g');

  // Caller-declared source statements are deliberately a separate footer channel. They
  // follow every mandatory disclosure, retain renderer-owned attribution, and carry the
  // helper-inserted FSI/PDI pair. `unicode-bidi=plaintext` makes each wrapped SVG text
  // element an independent bidi paragraph; a continued RTL line cannot reorder a prior
  // mandatory disclosure or the attribution on the first line.
  writer.open('g', [['data-source-statements', 'true']]);
  for (const statement of plan.sourceStatements) {
    writer.open('g', [
      ['data-source-statement-kind', statement.kind],
      ['data-source-statement-attribution', statement.attribution],
      ['data-source-statement-bidi-isolation', statement.bidiIsolation],
      ['data-source-statement-text', statement.text],
    ]);
    const lines = wrapDisclosureText(statement.text, plan.width);
    for (let index = 0; index < lines.length; index++) {
      const line = lines[index];
      writer.text('text', line, [
        ['x', DISCLOSURE_HORIZONTAL_INSET],
        ['y', formatCoordinate(disclosureY)],
        ['text-anchor', 'start'],
        ['font-size', DISCLOSURE_FONT_SIZE],
        ['fill', colors.mutedText],
        ['font-family', 'sans-serif'],
        ['textLength', formatCoordinate(disclosureRenderedTextLength(line, plan.width))],
        ['lengthAdjust', 'spacingAndGlyphs'],
        ['unicode-bidi', 'plaintext'],
        ['data-source-statement-line', index],
        ['aria-hidden', 'true'],
      ]);
      disclosureY += DISCLOSURE_LINE_HEIGHT;
    }
    writer.close('g');
  }
  writer.close('g');

  writer.close(translation === null ? 'svg' : 'g');

  const svg = writer.toString();
  const counts = countPlanResources(plan);

  return {
    svg,
    digest: digestOf(svg),
    markCount: counts.markCount,
    textCount: counts.textCount,
    width: plan.width,
    height: plan.height,
  };
}

/**
 * Render a plan to normative standalone SVG. Pure: no clock, no environment, no
 * filesystem, no network, no random state. The historical byte sequence is preserved:
 * the default identity prefix remains exactly `plan.figureId` and the document writer
 * receives the same ordered attributes and figure body as before this extraction.
 */
export function renderSvg(
  plan: RenderPlanV1,
  digestOf: (text: string) => string,
): SvgReport {
  return emitFigureTree(plan, digestOf, { kind: 'document' });
}

/**
 * Package-private foundation for FigureBundleV1. This is intentionally absent from
 * `cortexel/render-svg`: only a future bundle compiler that already holds closed child
 * plans may call it. The returned fragment is not a standalone SVG document.
 */
export function renderTranslationOnlySvgFragmentForBundleInternal(
  plan: RenderPlanV1,
  options: TranslationOnlySvgFragmentOptions,
  digestOf: (text: string) => string,
): TranslationOnlySvgFragmentReport {
  // Preserve the OutputAuthority boundary: unlike the historical internal standalone
  // writer, this new composition path refuses a copied or caller-constructed plan before
  // reading any property from it.
  if (!isClosedPlainRenderPlanForAuthorityV1(plan)) {
    throw new Error(
      'translated SVG fragments require the exact closed RenderPlan capability produced by Cortexel',
    );
  }
  const container = {
    kind: 'translated_fragment',
    idNamespace: options.idNamespace,
    x: options.x,
    y: options.y,
  } as const;
  const idPrefix = requireTranslationOnlyContainer(container, plan).idPrefix;
  const report = emitFigureTree(plan, digestOf, container);
  return Object.freeze({
    fragment: report.svg,
    digest: report.digest,
    idPrefix,
    markCount: report.markCount,
    textCount: report.textCount,
    width: report.width,
    height: report.height,
    translation: Object.freeze({ x: container.x, y: container.y }),
  });
}
